<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>每日视界 - 国内领先的新闻资讯平台</title>
    <style>
        :root {
            --primary-color: #1a3c6e;
            --accent-color: #c0392b;
            --text-dark: #333;
            --text-light: #666;
            --bg-light: #f4f4f4;
            --white: #ffffff;
            --border-color: #e0e0e0;
        }
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            line-height: 1.6;
            color: var(--text-dark);
            background-color: var(--white);
        }
        a {
            text-decoration: none;
            color: inherit;
        }
        a:hover {
            color: var(--primary-color);
        }
        /* Header */
        header {
            background-color: var(--white);
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 0;
            z-index: 100;
        }
        .top-bar {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 5px 0;
            font-size: 0.85rem;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }
        .top-bar .container {
            display: flex;
            justify-content: space-between;
        }
        .nav-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 0;
        }
        .logo {
            font-size: 1.8rem;
            font-weight: bold;
            color: var(--primary-color);
        }
        nav ul {
            display: flex;
            list-style: none;
            gap: 20px;
        }
        nav a {
            font-weight: 500;
            font-size: 1rem;
        }
        .mobile-menu-btn {
            display: none;
        }
        /* Hero Section */
        .hero {
            margin: 30px 0;
        }
        .hero-content {
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 30px;
        }
        .main-story {
            position: relative;
            background: #eee;
            min-height: 400px;
            border-radius: 8px;
            overflow: hidden;
            display: flex;
            align-items: flex-end;
        }
        .main-story .placeholder-img {
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background: linear-gradient(135deg, #e0e0e0 0%, #cfcfcf 100%);
            display: flex;
            justify-content: center;
            align-items: center;
            color: #999;
            font-size: 3rem;
            z-index: 1;
        }
        .main-story .overlay {
            position: relative;
            z-index: 2;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            width: 100%;
            padding: 40px;
            color: var(--white);
        }
        .main-story h1 {
            font-size: 2.2rem;
            margin-bottom: 10px;
            line-height: 1.2;
        }
        .main-story .meta {
            font-size: 0.9rem;
            color: #ddd;
        }
        .side-stories {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }
        .side-card {
            background: var(--white);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 20px;
            flex: 1;
        }
        .side-card h3 {
            font-size: 1.1rem;
            margin-bottom: 8px;
        }
        .side-card .meta {
            font-size: 0.8rem;
            color: var(--text-light);
        }
        .tag {
            display: inline-block;
            background: var(--primary-color);
            color: var(--white);
            padding: 2px 8px;
            font-size: 0.7rem;
            border-radius: 4px;
            margin-bottom: 8px;
        }
        .tag.urgent { background: var(--accent-color); }

        /* Latest News Section */
        .section-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin: 40px 0 20px;
            border-bottom: 2px solid var(--border-color);
            padding-bottom: 10px;
        }
        .section-header h2 {
            font-size: 1.5rem;
            color: var(--primary-color);
        }
        .news-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 30px;
        }
        .news-card {
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
            transition: transform 0.2s;
        }
        .news-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.1);
        }
        .card-img {
            height: 180px;
            background: #eee;
            display: flex;
            justify-content: center;
            align-items: center;
            color: #999;
        }
        .card-body {
            padding: 20px;
        }
        .card-body h3 {
            font-size: 1.2rem;
            margin-bottom: 10px;
            line-height: 1.4;
        }
        .card-body p {
            font-size: 0.95rem;
            color: var(--text-light);
            margin-bottom: 15px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }
        /* Newsletter */
        .newsletter {
            background: var(--bg-light);
            padding: 40px 0;
            margin-top: 50px;
            text-align: center;
        }
        .newsletter input {
            padding: 12px;
            width: 300px;
            border: 1px solid #ccc;
            border-radius: 4px;
            margin-right: 10px;
        }
        .newsletter button {
            padding: 12px 24px;
            background: var(--primary-color);
            color: var(--white);
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        /* Footer */
        footer {
            background: var(--primary-color);
            color: var(--white);
            padding: 40px 0;
            margin-top: 60px;
        }
        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 40px;
        }
        .footer-col h4 {
            margin-bottom: 20px;
            border-bottom: 1px solid rgba(255,255,255,0.2);
            padding-bottom: 10px;
        }
        .footer-col ul {
            list-style: none;
        }
        .footer-col ul li {
            margin-bottom: 10px;
        }
        .footer-col ul li a {
            color: #ddd;
        }
        .copyright {
            text-align: center;
            margin-top: 40px;
            padding-top: 20px;
            border-top: 1px solid rgba(255,255,255,0.1);
            font-size: 0.9rem;
            color: #aaa;
        }
        /* Responsive */
        @media (max-width: 768px) {
            .hero-content {
                grid-template-columns: 1fr;
            }
            .nav-links {
                display: none; /* Simplified for mobile demo */
            }
            .main-story h1 {
                font-size: 1.5rem;
            }
            .newsletter input {
                width: 100%;
                margin-bottom: 10px;
            }
            .newsletter button {
                width: 100%;
            }
        }
    </style>
</head>
<body>

