            <span>订阅 | 登录 | 注册</span>
        </div>
    </div>
    <div class="container nav-container">
        <a href="index.html" class="logo">每日视界</a>
        <nav class="nav-links">
            <ul>
                <li><a href="index.html" style="color: var(--primary-color); font-weight: bold;">首页</a></li>
